mapper.select:
/* saleson.shop.remittance.RemittanceMapper.getRemittanceFinishingCountByParam */
SELECT COUNT(1)
FROM
	OP_REMITTANCE R
		INNER JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID


		AND R.SELLER_ID = #{sellerId}





			AND R.FINISHING_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')



			AND R.FINISHING_DATE BETWEEN #{startDate} AND #{endDate}

/* saleson.shop.remittance.RemittanceMapper.getRemittanceFinishingListByParam */
SELECT S.*, (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV L WHERE L.LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM, R.REMITTANCE_ID, R.CONFIRM_DATE, R.FINISHING_DATE, R.FINISHING_AMOUNT, R.FINISHING_MANAGER_NAME, R.BANK_NAME AS REMITTANCE_BANK_NAME, R.BANK_IN_NAME AS REMITTANCE_BANK_IN_NAME, R.BANK_ACCOUNT_NUMBER AS REMITTANCE_BANK_ACCOUNT_NUMBER, R.CREATED_DATE AS REMITTANCE_CREATED_DATE, (SELECT REMITTANCE_STATUS_CODE FROM OP_ORDER_ITEM WHERE R.REMITTANCE_ID = REMITTANCE_ID LIMIT 1) AS REMITTANCE_STATUS_CODE, (SELECT SUM(T.TOTAL) AS TOTAL FROM ( SELECT (CASE WHEN OI.CANCEL_FLAG = 'Y' THEN -OI.SUPPLY_PRICE + OI.SELLER_POINT + (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) + OI.SET_DISCOUNT_PRICE ELSE OI.SUPPLY_PRICE - OI.SELLER_POINT - (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) - OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY AS TOTAL FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OI.REMITTANCE_ID = R.REMITTANCE_ID
UNION ALL
SELECT (CASE WHEN OS.RETURN_FLAG = 'Y' THEN -OS.REMITTANCE_AMOUNT ELSE OS.REMITTANCE_AMOUNT END) AS TOTAL FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OS.REMITTANCE_ID = R.REMITTANCE_ID
UNION ALL
SELECT (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OAP.REMITTANCE_ID = R.REMITTANCE_ID ) T) AS SALES_AMOUNT FROM OP_REMITTANCE R INNER JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID
AND R.SELLER_ID = #{sellerId}
AND R.FINISHING_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND R.FINISHING_DATE BETWEEN #{startDate} AND #{endDate}
ORDER BY R.REMITTANCE_ID DESC

/* saleson.shop.remittance.RemittanceMapper.getRemittanceFinishingDetailCountByParam */
SELECT COUNT(*)
FROM
	OP_REMITTANCE_DETAIL RD

	RD.REMITTANCE_ID = #{remittanceId}

/* saleson.shop.remittance.RemittanceMapper.getRemittanceFinishingDetailListByParam */ SELECT T_A.* , T_A.BUYER_NAME_ENC AS BUYER_NAME FROM ( SELECT * , ( SELECT USER_NAME FROM OP_USER U WHERE U.USER_ID = ( SELECT USER_ID FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = DTL.ORDER_CODE LIMIT 1 ) ) AS BUYER_NAME_ENC , ( SELECT PAY_DATE FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = DTL.ORDER_CODE LIMIT 1 ) AS PAY_DATE FROM (
SELECT RD.* FROM OP_REMITTANCE_DETAIL RD
RD.REMITTANCE_ID = #{remittanceId}
ORDER BY RD.REMITTANCE_DETAIL_ID DESC
) DTL ) T_A

mapper.sql:
FROM
	OP_ORDER_ITEM OI
		INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'



			AND OI.CANCEL_FLAG = 'Y'






			AND OI.SELLER_ID != #{defaultOpmanagerSellerId}



			AND OI.SELLER_ID = #{sellerId}


		AND REMITTANCE_STATUS_CODE != '0'

		AND (
			(OI.CANCEL_FLAG = 'N' AND OI.REMITTANCE_STATUS_CODE = '1' AND OI.CLAIM_QUANTITY = 0)
			OR (OI.CANCEL_FLAG = 'Y' AND OI.REMITTANCE_STATUS_CODE = '2')
		)



				AND DATE_FORMAT(OI.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}


				AND OI.REMITTANCE_DATE = #{startDate}



		AND OI.SUPPLY_PRICE > 0

FROM
	OP_ORDER_SHIPPING OS
		INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'


		AND OS.SELLER_ID != #{defaultOpmanagerSellerId}



		AND OS.SELLER_ID = #{sellerId}


	AND (REMITTANCE_STATUS_CODE = '1' OR REMITTANCE_STATUS_CODE = '2')



			AND DATE_FORMAT(OS.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}


			AND OS.REMITTANCE_DATE = #{startDate}



	AND OS.REMITTANCE_AMOUNT > 0

FROM
	OP_ORDER_ADD_PAYMENT OAP
		INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'


		AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}



		AND OAP.SELLER_ID = #{sellerId}


	AND REMITTANCE_STATUS_CODE != '0'
	AND REMITTANCE_STATUS_CODE = #{statusCode}



			AND DATE_FORMAT(OAP.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}


			AND OAP.REMITTANCE_DATE = #{startDate}



	AND OAP.REMITTANCE_AMOUNT > 0


	AND OS.SELLER_ID != #{defaultOpmanagerSellerId}



	AND OS.SELLER_ID = #{sellerId}


AND (REMITTANCE_STATUS_CODE = '1' OR REMITTANCE_STATUS_CODE = '2')



		AND DATE_FORMAT(OS.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}


		AND OS.REMITTANCE_DATE = #{startDate}



AND OS.REMITTANCE_AMOUNT > 0


	AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}



	AND OAP.SELLER_ID = #{sellerId}


AND REMITTANCE_STATUS_CODE != '0'
AND REMITTANCE_STATUS_CODE = #{statusCode}



		AND DATE_FORMAT(OAP.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}


		AND OAP.REMITTANCE_DATE = #{startDate}



AND OAP.REMITTANCE_AMOUNT > 0


	AND OI.SELLER_ID != #{defaultOpmanagerSellerId}



	AND OI.SELLER_ID = #{sellerId}


AND REMITTANCE_STATUS_CODE != '0'

AND (
	(OI.CANCEL_FLAG = 'N' AND OI.REMITTANCE_STATUS_CODE = '1' AND OI.CLAIM_QUANTITY = 0)
	OR (OI.CANCEL_FLAG = 'Y' AND OI.REMITTANCE_STATUS_CODE = '2')
)



		AND DATE_FORMAT(OI.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}


		AND OI.REMITTANCE_DATE = #{startDate}



AND OI.SUPPLY_PRICE > 0

mapper.select:
/* saleson.shop.remittance.RemittanceMapper.getRemittanceFinishingAmountValidateByParam */ SELECT CASE WHEN M1.TOTAL != M2.TOTAL THEN 0 ELSE M1.TOTAL END FROM ( SELECT SUM(REMITTANCE_PRICE * QUANTITY) AS TOTAL FROM OP_REMITTANCE_DETAIL WHERE REMITTANCE_ID = #{remittanceId} ) M1, ( SELECT SUM(T.TOTAL) AS TOTAL FROM ( SELECT (CASE WHEN OI.CANCEL_FLAG = 'Y' THEN -OI.SUPPLY_PRICE + OI.SELLER_POINT + (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) + OI.SET_DISCOUNT_PRICE ELSE OI.SUPPLY_PRICE - OI.SELLER_POINT - (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) - OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY AS TOTAL FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OI.REMITTANCE_ID = #{remittanceId}
UNION ALL
SELECT (CASE WHEN OS.RETURN_FLAG = 'Y' THEN -OS.REMITTANCE_AMOUNT ELSE OS.REMITTANCE_AMOUNT END) AS TOTAL FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OS.REMITTANCE_ID = #{remittanceId}
UNION ALL
SELECT (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OAP.REMITTANCE_ID = #{remittanceId} ) T ) M2

mapper.sql:
SELECT S.*, T.REMITTANCE_DATE, T.ITEM_TOTAL_COMMISSION_BASE_AMOUNT, T.ITEM_TOTAL_COMMISSION_AMOUNT, T.ITEM_TOTAL_SUPPLY_AMOUNT, T.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, T.ITEM_TOTAL_SELLER_POINT_AMOUNT, T.ITEM_TOTAL_SET_DISCOUNT_AMOUNT, T.SHIPPING_TOTAL_AMOUNT, T.ADD_PAYMENT_TOTAL_AMOUNT, T.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, T.CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT G.SELLER_ID, G.REMITTANCE_DATE, SUM(G.ITEM_TOTAL_COMMISSION_BASE_AMOUNT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(G.ITEM_TOTAL_COMMISSION_AMOUNT) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(G.ITEM_TOTAL_SUPPLY_AMOUNT) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_POINT_AMOUNT) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(G.ITEM_TOTAL_SET_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(G.SHIPPING_TOTAL_AMOUNT) AS SHIPPING_TOTAL_AMOUNT, SUM(G.ADD_PAYMENT_TOTAL_AMOUNT) AS ADD_PAYMENT_TOTAL_AMOUNT, SUM(G.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.CANCEL_SHIPPING_TOTAL_AMOUNT) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT M.SELLER_ID, M.REMITTANCE_DATE, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SUPPLY_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_POINT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SET_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS SHIPPING_TOTAL_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ADD_PAYMENT' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ADD_PAYMENT_TOTAL_AMOUNT,
(CASE WHEN M.PRODUCT_TYPE = 'ITEM' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM (
SELECT OI.SELLER_ID, OI.REMITTANCE_DATE, OI.CANCEL_FLAG, OI.REMITTANCE_STATUS_CODE, 'ITEM' AS PRODUCT_TYPE, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_BASE_PRICE ELSE -OI.COMMISSION_BASE_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_BASE_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_PRICE ELSE -OI.COMMISSION_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SUPPLY_PRICE ELSE -OI.SUPPLY_PRICE END) * OI.QUANTITY) AS TOTAL_SUPPLY_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN 1 ELSE -1 END) * (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) * OI.QUANTITY) AS TOTAL_SELLER_DISCOUNT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SELLER_POINT ELSE -OI.SELLER_POINT END) * OI.QUANTITY) AS TOTAL_SELLER_POINT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SET_DISCOUNT_PRICE ELSE -OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY) AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND REMITTANCE_STATUS_CODE != '0'
AND ( (OI.CANCEL_FLAG = 'N' AND OI.REMITTANCE_STATUS_CODE = '1' AND OI.CLAIM_QUANTITY = 0) OR (OI.CANCEL_FLAG = 'Y' AND OI.REMITTANCE_STATUS_CODE = '2') )
AND DATE_FORMAT(OI.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}
AND OI.REMITTANCE_DATE = #{startDate}
AND OI.SUPPLY_PRICE > 0
GROUP BY OI.SELLER_ID, OI.REMITTANCE_DATE, OI.CANCEL_FLAG
UNION ALL
SELECT OS.SELLER_ID, OS.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OS.REMITTANCE_STATUS_CODE, 'SHIPPING' AS PRODUCT_TYPE, SUM(CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OS.SELLER_ID != #{defaultOpmanagerSellerId}
AND OS.SELLER_ID = #{sellerId}
AND (REMITTANCE_STATUS_CODE = '1' OR REMITTANCE_STATUS_CODE = '2')
AND DATE_FORMAT(OS.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}
AND OS.REMITTANCE_DATE = #{startDate}
AND OS.REMITTANCE_AMOUNT > 0
GROUP BY OS.SELLER_ID, OS.REMITTANCE_DATE
UNION ALL
SELECT OAP.SELLER_ID, OAP.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OAP.REMITTANCE_STATUS_CODE, 'ADD_PAYMENT' AS PRODUCT_TYPE, SUM(CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}
AND OAP.SELLER_ID = #{sellerId}
AND REMITTANCE_STATUS_CODE != '0' AND REMITTANCE_STATUS_CODE = #{statusCode}
AND DATE_FORMAT(OAP.REMITTANCE_DATE, '%Y%m%d') BETWEEN #{startDate} AND #{endDate}
AND OAP.REMITTANCE_DATE = #{startDate}
AND OAP.REMITTANCE_AMOUNT > 0
GROUP BY OAP.SELLER_ID, OAP.REMITTANCE_DATE ) M ) G GROUP BY G.SELLER_ID, G.REMITTANCE_DATE ) T INNER JOIN OP_SELLER S ON T.SELLER_ID = S.SELLER_ID

mapper.select:
/* saleson.shop.remittance.RemittanceMapper.getRemittanceConfirmCountByParam */ SELECT COUNT(1) FROM ( SELECT S.*, T.REMITTANCE_DATE, T.ITEM_TOTAL_COMMISSION_BASE_AMOUNT, T.ITEM_TOTAL_COMMISSION_AMOUNT, T.ITEM_TOTAL_SUPPLY_AMOUNT, T.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, T.ITEM_TOTAL_SELLER_POINT_AMOUNT, T.ITEM_TOTAL_SET_DISCOUNT_AMOUNT, T.SHIPPING_TOTAL_AMOUNT, T.ADD_PAYMENT_TOTAL_AMOUNT, T.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, T.CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT G.SELLER_ID, G.REMITTANCE_DATE, SUM(G.ITEM_TOTAL_COMMISSION_BASE_AMOUNT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(G.ITEM_TOTAL_COMMISSION_AMOUNT) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(G.ITEM_TOTAL_SUPPLY_AMOUNT) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_POINT_AMOUNT) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(G.ITEM_TOTAL_SET_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(G.SHIPPING_TOTAL_AMOUNT) AS SHIPPING_TOTAL_AMOUNT, SUM(G.ADD_PAYMENT_TOTAL_AMOUNT) AS ADD_PAYMENT_TOTAL_AMOUNT, SUM(G.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.CANCEL_SHIPPING_TOTAL_AMOUNT) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT M.SELLER_ID, M.REMITTANCE_DATE, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SUPPLY_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_POINT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SET_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS SHIPPING_TOTAL_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ADD_PAYMENT' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ADD_PAYMENT_TOTAL_AMOUNT,
(CASE WHEN M.PRODUCT_TYPE = 'ITEM' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM (
SELECT OI.SELLER_ID, OI.REMITTANCE_DATE, OI.CANCEL_FLAG, OI.REMITTANCE_STATUS_CODE, 'ITEM' AS PRODUCT_TYPE, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_BASE_PRICE ELSE -OI.COMMISSION_BASE_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_BASE_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_PRICE ELSE -OI.COMMISSION_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SUPPLY_PRICE ELSE -OI.SUPPLY_PRICE END) * OI.QUANTITY) AS TOTAL_SUPPLY_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN 1 ELSE -1 END) * (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) * OI.QUANTITY) AS TOTAL_SELLER_DISCOUNT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SELLER_POINT ELSE -OI.SELLER_POINT END) * OI.QUANTITY) AS TOTAL_SELLER_POINT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SET_DISCOUNT_PRICE ELSE -OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY) AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND (OI.REMITTANCE_STATUS_CODE = '3' OR OI.REMITTANCE_STATUS_CODE = '4')
AND OI.REMITTANCE_STATUS_CODE = '3'
AND OI.REMITTANCE_STATUS_CODE = '4'
AND OI.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OI.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OI.REMITTANCE_DATE = #{startDate}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
AND OI.SUPPLY_PRICE > 0
GROUP BY OI.SELLER_ID, OI.REMITTANCE_DATE, OI.CANCEL_FLAG
UNION ALL
SELECT OS.SELLER_ID, OS.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OS.REMITTANCE_STATUS_CODE, 'SHIPPING' AS PRODUCT_TYPE, SUM(CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OS.SELLER_ID != #{defaultOpmanagerSellerId}
AND OS.SELLER_ID = #{sellerId}
AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')
AND REMITTANCE_STATUS_CODE = '3'
AND REMITTANCE_STATUS_CODE = '4'
AND OS.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OS.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OS.REMITTANCE_DATE = #{startDate}
AND OS.REMITTANCE_AMOUNT > 0
GROUP BY OS.SELLER_ID, OS.REMITTANCE_DATE
UNION ALL
SELECT OAP.SELLER_ID, OAP.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OAP.REMITTANCE_STATUS_CODE, 'ADD_PAYMENT' AS PRODUCT_TYPE, SUM(CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}
AND OAP.SELLER_ID = #{sellerId}
AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')
AND REMITTANCE_STATUS_CODE = '3'
AND REMITTANCE_STATUS_CODE = '4'
AND OAP.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OAP.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OAP.REMITTANCE_DATE = #{startDate}
AND OAP.REMITTANCE_AMOUNT > 0
GROUP BY OAP.SELLER_ID, OAP.REMITTANCE_DATE ) M ) G GROUP BY G.SELLER_ID, G.REMITTANCE_DATE ) T INNER JOIN OP_SELLER S ON T.SELLER_ID = S.SELLER_ID ) T

/* saleson.shop.remittance.RemittanceMapper.getRemittanceConfirmListByParam */
SELECT S.*, T.LOCGOV_CODE,
(SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV L WHERE L.LOCGOV_CODE = T.LOCGOV_CODE) AS LOCGOV_NM, T.REMITTANCE_DATE, T.CANCEL_FLAG, T.REMITTANCE_STATUS_CODE, T.PRODUCT_TYPE, T.ITEM_TOTAL_COMMISSION_BASE_AMOUNT, T.ITEM_TOTAL_COMMISSION_AMOUNT, T.ITEM_TOTAL_SUPPLY_AMOUNT, T.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, T.ITEM_TOTAL_SELLER_POINT_AMOUNT, T.ITEM_TOTAL_SET_DISCOUNT_AMOUNT, T.SHIPPING_TOTAL_AMOUNT, T.ADD_PAYMENT_TOTAL_AMOUNT, T.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, T.CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT G.SELLER_ID, G.LOCGOV_CODE,
G.REMITTANCE_DATE, G.CANCEL_FLAG, G.REMITTANCE_STATUS_CODE, G.PRODUCT_TYPE, SUM(G.ITEM_TOTAL_COMMISSION_BASE_AMOUNT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(G.ITEM_TOTAL_COMMISSION_AMOUNT) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(G.ITEM_TOTAL_SUPPLY_AMOUNT) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_POINT_AMOUNT) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(G.ITEM_TOTAL_SET_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(G.SHIPPING_TOTAL_AMOUNT) AS SHIPPING_TOTAL_AMOUNT, SUM(G.ADD_PAYMENT_TOTAL_AMOUNT) AS ADD_PAYMENT_TOTAL_AMOUNT, SUM(G.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.CANCEL_SHIPPING_TOTAL_AMOUNT) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT M.SELLER_ID, M.LOCGOV_CODE,
M.REMITTANCE_DATE, M.CANCEL_FLAG, M.REMITTANCE_STATUS_CODE, M.PRODUCT_TYPE, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SUPPLY_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_POINT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SET_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS SHIPPING_TOTAL_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ADD_PAYMENT' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ADD_PAYMENT_TOTAL_AMOUNT,
(CASE WHEN M.PRODUCT_TYPE = 'ITEM' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM (
SELECT OI.SELLER_ID, S.LOCGOV_CODE, OI.REMITTANCE_DATE, OI.CANCEL_FLAG, OI.REMITTANCE_STATUS_CODE, 'ITEM' AS PRODUCT_TYPE, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_BASE_PRICE ELSE -OI.COMMISSION_BASE_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_BASE_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_PRICE ELSE -OI.COMMISSION_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SUPPLY_PRICE ELSE -OI.SUPPLY_PRICE END) * OI.QUANTITY) AS TOTAL_SUPPLY_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN 1 ELSE -1 END) * (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) * OI.QUANTITY) AS TOTAL_SELLER_DISCOUNT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SELLER_POINT ELSE -OI.SELLER_POINT END) * OI.QUANTITY) AS TOTAL_SELLER_POINT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SET_DISCOUNT_PRICE ELSE -OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY) AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON S.SELLER_ID = OI.SELLER_ID
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND (OI.REMITTANCE_STATUS_CODE = '3' OR OI.REMITTANCE_STATUS_CODE = '4')
AND OI.REMITTANCE_STATUS_CODE = '3'
AND OI.REMITTANCE_STATUS_CODE = '4'
AND OI.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OI.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OI.REMITTANCE_DATE = #{startDate}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
AND OI.SUPPLY_PRICE > 0
GROUP BY OI.SELLER_ID, OI.REMITTANCE_DATE, OI.CANCEL_FLAG
UNION ALL
SELECT OS.SELLER_ID, S.LOCGOV_CODE, OS.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OS.REMITTANCE_STATUS_CODE, 'SHIPPING' AS PRODUCT_TYPE, SUM(CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON S.SELLER_ID = OS.SELLER_ID
AND OS.SELLER_ID != #{defaultOpmanagerSellerId}
AND OS.SELLER_ID = #{sellerId}
AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')
AND REMITTANCE_STATUS_CODE = '3'
AND REMITTANCE_STATUS_CODE = '4'
AND OS.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OS.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OS.REMITTANCE_DATE = #{startDate}
AND OS.REMITTANCE_AMOUNT > 0
GROUP BY OS.SELLER_ID, OS.REMITTANCE_DATE
UNION ALL
SELECT OAP.SELLER_ID, S.LOCGOV_CODE, OAP.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OAP.REMITTANCE_STATUS_CODE, 'ADD_PAYMENT' AS PRODUCT_TYPE, SUM(CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON S.SELLER_ID = OAP.SELLER_ID
AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}
AND OAP.SELLER_ID = #{sellerId}
AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')
AND REMITTANCE_STATUS_CODE = '3'
AND REMITTANCE_STATUS_CODE = '4'
AND OAP.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OAP.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OAP.REMITTANCE_DATE = #{startDate}
AND OAP.REMITTANCE_AMOUNT > 0
GROUP BY OAP.SELLER_ID, OAP.REMITTANCE_DATE ) M ) G GROUP BY G.SELLER_ID, G.REMITTANCE_DATE ) T INNER JOIN OP_SELLER S ON T.SELLER_ID = S.SELLER_ID

/* saleson.shop.remittance.RemittanceMapper.getRemittanceConfirmDetailCountByParam */

SELECT SUM(T.COUNT) AS `COUNT` FROM (
	SELECT
		'ITEM' AS PRODUCT_TYPE,
		COUNT(*) AS `COUNT`
	FROM
		OP_ORDER_ITEM OI
			INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
			JOIN OP_ORDER_PAYMENT OP ON OI.ORDER_CODE = OP.ORDER_CODE
			JOIN OP_USER U ON OI.USER_ID = U.USER_ID



				AND OI.CANCEL_FLAG = 'Y'






				AND OI.SELLER_ID != #{defaultOpmanagerSellerId}



				AND OI.SELLER_ID = #{sellerId}




			AND (OI.REMITTANCE_STATUS_CODE = '3' OR OI.REMITTANCE_STATUS_CODE = '4')




					AND OI.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}


					AND OI.REMITTANCE_DATE = #{startDate}






						AND OI.ORDER_CODE = #{query}


						AND U.USER_NAME = #{query}


						AND OI.ITEM_USER_CODE = #{query}


						AND OI.ITEM_NAME = #{query}




			AND OI.SUPPLY_PRICE > 0


	UNION ALL

	SELECT
		'SHIPPING' AS PRODUCT_TYPE,
		COUNT(*) AS `COUNT`
	FROM
		OP_ORDER_SHIPPING OS
			INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'


			AND OS.SELLER_ID != #{defaultOpmanagerSellerId}



			AND OS.SELLER_ID = #{sellerId}



		AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')




				AND OS.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}


				AND OS.REMITTANCE_DATE = #{startDate}



		AND OS.REMITTANCE_AMOUNT > 0


	UNION ALL

	SELECT
		'ADD_PAYMENT' AS PRODUCT_TYPE,
		COUNT(*) AS `COUNT`
	FROM
		OP_ORDER_ADD_PAYMENT OAP
			INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'


			AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}



			AND OAP.SELLER_ID = #{sellerId}




		AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')




				AND OAP.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}


				AND OAP.REMITTANCE_DATE = #{startDate}



		AND OAP.REMITTANCE_AMOUNT > 0


) T

/* saleson.shop.remittance.RemittanceMapper.getRemittanceConfirmDetailListByParam */
SELECT T_A.* , T_A.BUYER_NAME_ENC AS BUYER_NAME FROM ( SELECT T.* FROM ( SELECT OI.ORDER_CODE, OI.ORDER_SEQUENCE, CONCAT('ITEM-', OI.ORDER_CODE, '-', OI.ORDER_SEQUENCE, '-', OI.ITEM_SEQUENCE) AS REMITTANCE_KEY, OI.ITEM_USER_CODE, OI.REMITTANCE_STATUS_CODE, 'ITEM' AS PRODUCT_TYPE, OI.REMITTANCE_DATE, OI.ITEM_NAME, OI.OPTIONS, OI.COMMISSION_BASE_PRICE, OI.COMMISSION_RATE, OI.COMMISSION_PRICE, OI.COMMISSION_TYPE, OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END) AS SELLER_DISCOUNT_PRICE, OI.SELLER_DISCOUNT_DETAIL, OI.SELLER_POINT, OI.SET_ITEM_FLAG, OI.SET_DISCOUNT_PRICE, OI.SALE_PRICE, (CASE WHEN OI.CANCEL_FLAG = 'Y' THEN -OI.SUPPLY_PRICE ELSE OI.SUPPLY_PRICE END) AS SUPPLY_PRICE, (CASE WHEN OI.CANCEL_FLAG = 'Y' THEN -OI.SUPPLY_PRICE + OI.SELLER_POINT + (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) + OI.SET_DISCOUNT_PRICE ELSE OI.SUPPLY_PRICE - OI.SELLER_POINT - (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) - OI.SET_DISCOUNT_PRICE END) AS REMITTANCE_PRICE, OI.QUANTITY, OP.REMAINING_AMOUNT, OI.PAY_DATE, OI.CONFIRM_DATE, OI.SELLER_ID, U.USER_NAME AS BUYER_NAME_ENC FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_ORDER_PAYMENT OP ON OI.ORDER_CODE = OP.ORDER_CODE JOIN OP_USER U ON OI.USER_ID = U.USER_ID
AND OI.CANCEL_FLAG = 'Y'
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND (OI.REMITTANCE_STATUS_CODE = '3' OR OI.REMITTANCE_STATUS_CODE = '4')
AND OI.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OI.REMITTANCE_DATE = #{startDate}
AND OI.SUPPLY_PRICE > 0
AND OI.ORDER_CODE = #{query}
AND U.USER_NAME = #{query}
AND OI.ITEM_USER_CODE = #{query}
AND OI.ITEM_NAME = #{query}
UNION ALL
SELECT OS.ORDER_CODE, OS.ORDER_SEQUENCE, CONCAT('SHIPPING-', OS.ORDER_CODE, '-', OS.ORDER_SEQUENCE, '-', OS.SHIPPING_SEQUENCE) AS REMITTANCE_KEY, '' AS ITEM_USER_CODE, OS.REMITTANCE_STATUS_CODE, 'SHIPPING' AS PRODUCT_TYPE, OS.REMITTANCE_DATE, '배송비' AS ITEM_NAME, '' AS OPTIONS, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS COMMISSION_BASE_PRICE, 0 AS COMMISSION_RATE, 0 AS COMMISSION_PRICE, '0' AS COMMISSION_TYPE, 0 AS SELLER_DISCOUNT_PRICE, '' AS SELLER_DISCOUNT_DETAIL, 0 AS SELLER_POINT, '' AS SET_ITEM_FLAG, 0 AS SET_DISCOUNT_PRICE, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS SALE_PRICE, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS SUPPLY_PRICE, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS REMITTANCE_PRICE, 1 AS QUANTITY, 0 AS REMAINING_AMOUNT, '' AS PAY_DATE, '' AS CONFIRM_DATE, 0 AS SELLER_ID, '' AS BUYER_NAME_ENC FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OS.SELLER_ID != #{defaultOpmanagerSellerId}
AND OS.SELLER_ID = #{sellerId}
AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')
AND OS.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OS.REMITTANCE_DATE = #{startDate}
AND OS.REMITTANCE_AMOUNT > 0
UNION ALL
SELECT OAP.ORDER_CODE, '' AS ORDER_SEQUENCE, CONCAT('ADD_PAYMENT-', OAP.ORDER_CODE, '-' , OAP.ADD_PAYMENT_ID) AS REMITTANCE_KEY, '' AS ITEM_USER_CODE, OAP.REMITTANCE_STATUS_CODE, 'ADD_PAYMENT' AS PRODUCT_TYPE, OAP.REMITTANCE_DATE, OAP.SUBJECT AS ITEM_NAME, '' AS OPTIONS, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS COMMISSION_BASE_PRICE, 0 AS COMMISSION_RATE, 0 AS COMMISSION_PRICE, '0' AS COMMISSION_TYPE, 0 AS SELLER_DISCOUNT_PRICE, '' AS SELLER_DISCOUNT_DETAIL, 0 AS SELLER_POINT, '' AS SET_ITEM_FLAG, 0 AS SET_DISCOUNT_PRICE, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS SALE_PRICE, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS SUPPLY_PRICE, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS REMITTANCE_PRICE, 1 AS QUANTITY, 0 AS REMAINING_AMOUNT, '' AS PAY_DATE, '' AS CONFIRM_DATE, 0 AS SELLER_ID, '' AS BUYER_NAME_ENC FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}
AND OAP.SELLER_ID = #{sellerId}
AND (REMITTANCE_STATUS_CODE = '3' OR REMITTANCE_STATUS_CODE = '4')
AND OAP.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OAP.REMITTANCE_DATE = #{startDate}
AND OAP.REMITTANCE_AMOUNT > 0
) T ORDER BY T.ORDER_CODE DESC, T.PRODUCT_TYPE
) T_A

mapper.sql:
FROM OP_ORDER_SHIPPING OS
	INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'


		AND OS.SELLER_ID != #{defaultOpmanagerSellerId}



		AND OS.SELLER_ID = #{sellerId}


	AND (REMITTANCE_STATUS_CODE = '1' OR REMITTANCE_STATUS_CODE = '2')

	AND OS.REMITTANCE_EXPECTED_DATE BETWEEN #{startDate} AND #{endDate}
	AND OS.REMITTANCE_AMOUNT > 0

FROM OP_ORDER_ADD_PAYMENT OAP
	INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'


		AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}



		AND OAP.SELLER_ID = #{sellerId}


	AND (OAP.REMITTANCE_STATUS_CODE = '1' OR OAP.REMITTANCE_STATUS_CODE = '2')
	AND OAP.REMITTANCE_EXPECTED_DATE BETWEEN #{startDate} AND #{endDate}
	AND OAP.REMITTANCE_AMOUNT > 0

FROM OP_ORDER_ITEM OI
	INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'


		AND OI.SELLER_ID != #{defaultOpmanagerSellerId}



		AND OI.SELLER_ID = #{sellerId}


	AND OI.REMITTANCE_STATUS_CODE != '0'

	AND (
		(OI.CANCEL_FLAG = 'N' AND OI.REMITTANCE_STATUS_CODE = '1' AND OI.CLAIM_QUANTITY = 0)
		OR (OI.CANCEL_FLAG = 'Y' AND OI.REMITTANCE_STATUS_CODE = '2')
	)

	AND OI.REMITTANCE_EXPECTED_DATE BETWEEN #{startDate} AND #{endDate}
	AND OI.SUPPLY_PRICE > 0

mapper.select:
/* saleson.shop.remittance.RemittanceMapper.getRemittanceExpectedCountByParam */ SELECT COUNT(1) FROM ( SELECT S.*, (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV L WHERE L.LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM, T.REMITTANCE_DATE, T.REMITTANCE_EXPECTED_DATE, T.ITEM_TOTAL_COMMISSION_BASE_AMOUNT, T.ITEM_TOTAL_COMMISSION_AMOUNT, T.ITEM_TOTAL_SUPPLY_AMOUNT, T.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, T.ITEM_TOTAL_SELLER_POINT_AMOUNT, T.ITEM_TOTAL_SET_DISCOUNT_AMOUNT, T.SHIPPING_TOTAL_AMOUNT, T.ADD_PAYMENT_TOTAL_AMOUNT FROM ( SELECT M1.SELLER_ID, M1.REMITTANCE_DATE, M1.REMITTANCE_EXPECTED_DATE, SUM(M1.ITEM_TOTAL_COMMISSION_BASE_AMOUNT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(M1.ITEM_TOTAL_COMMISSION_AMOUNT) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(M1.ITEM_TOTAL_SUPPLY_AMOUNT) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(M1.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(M1.ITEM_TOTAL_SELLER_POINT_AMOUNT) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(M1.ITEM_TOTAL_SET_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(M1.SHIPPING_TOTAL_AMOUNT) AS SHIPPING_TOTAL_AMOUNT, SUM(M1.ADD_PAYMENT_TOTAL_AMOUNT) AS ADD_PAYMENT_TOTAL_AMOUNT FROM ( SELECT M.SELLER_ID, M.REMITTANCE_DATE, M.REMITTANCE_EXPECTED_DATE, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SUPPLY_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_POINT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SET_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS SHIPPING_TOTAL_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ADD_PAYMENT' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ADD_PAYMENT_TOTAL_AMOUNT FROM (
SELECT OI.SELLER_ID, 'ITEM' AS PRODUCT_TYPE, OI.REMITTANCE_DATE, OI.REMITTANCE_EXPECTED_DATE, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_BASE_PRICE ELSE -OI.COMMISSION_BASE_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_BASE_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_PRICE ELSE -OI.COMMISSION_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SUPPLY_PRICE ELSE -OI.SUPPLY_PRICE END) * OI.QUANTITY) AS TOTAL_SUPPLY_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN 1 ELSE -1 END) * (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) * OI.QUANTITY) AS TOTAL_SELLER_DISCOUNT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SELLER_POINT ELSE -OI.SELLER_POINT END) * OI.QUANTITY) AS TOTAL_SELLER_POINT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SET_DISCOUNT_PRICE ELSE -OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY) AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
AND S.REPRESENTATIVE_NAME = #{query}
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
AND OI.REMITTANCE_EXPECTED_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99') AND OI.SUPPLY_PRICE > 0 AND OI.REMITTANCE_ID IS NULL AND OI.ORDER_STATUS = '40'
GROUP BY OI.SELLER_ID, OI.REMITTANCE_DATE, OI.REMITTANCE_EXPECTED_DATE
UNION ALL
SELECT OS.SELLER_ID, 'SHIPPING' AS PRODUCT_TYPE, OS.REMITTANCE_DATE, OS.REMITTANCE_EXPECTED_DATE, SUM(CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT
FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON OS.SELLER_ID = S.SELLER_ID
AND OS.SELLER_ID != #{defaultOpmanagerSellerId}
AND OS.SELLER_ID = #{sellerId}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
AND S.REPRESENTATIVE_NAME = #{query}
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
AND OS.REMITTANCE_EXPECTED_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99') AND OS.REMITTANCE_AMOUNT > 0 AND OS.REMITTANCE_ID IS NULL
GROUP BY OS.SELLER_ID, OS.REMITTANCE_DATE, OS.REMITTANCE_EXPECTED_DATE
UNION ALL
SELECT OAP.SELLER_ID, 'ADD_PAYMENT' AS PRODUCT_TYPE, OAP.REMITTANCE_DATE, OAP.REMITTANCE_EXPECTED_DATE, SUM(CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT
FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON OAP.SELLER_ID = S.SELLER_ID
AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}
AND OAP.SELLER_ID = #{sellerId}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
AND S.REPRESENTATIVE_NAME = #{query}
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
AND OAP.REMITTANCE_EXPECTED_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99') AND OAP.REMITTANCE_AMOUNT > 0 AND OAP.REMITTANCE_ID IS NULL
GROUP BY OAP.SELLER_ID, OAP.REMITTANCE_DATE, OAP.REMITTANCE_EXPECTED_DATE
) M GROUP BY M.SELLER_ID, M.PRODUCT_TYPE, M.REMITTANCE_EXPECTED_DATE ) M1 GROUP BY M1.SELLER_ID, M1.REMITTANCE_EXPECTED_DATE ) T INNER JOIN OP_SELLER S ON T.SELLER_ID = S.SELLER_ID ) T

