'' AS REMITTANCE_DATE, T.OR_CNT, T.REMITTANCE_EXPECTED_DATE, T.ITEM_TOTAL_COMMISSION_BASE_AMOUNT, T.ITEM_TOTAL_COMMISSION_AMOUNT, T.ITEM_TOTAL_SUPPLY_AMOUNT, T.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, T.ITEM_TOTAL_SELLER_POINT_AMOUNT, T.ITEM_TOTAL_SET_DISCOUNT_AMOUNT, T.SHIPPING_TOTAL_AMOUNT, T.ADD_PAYMENT_TOTAL_AMOUNT FROM ( SELECT M1.SELLER_ID, M1.OR_CNT, M1.REMITTANCE_DATE, M1.REMITTANCE_EXPECTED_DATE, SUM(M1.ITEM_TOTAL_COMMISSION_BASE_AMOUNT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(M1.ITEM_TOTAL_COMMISSION_AMOUNT) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(M1.ITEM_TOTAL_SUPPLY_AMOUNT) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(M1.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(M1.ITEM_TOTAL_SELLER_POINT_AMOUNT) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(M1.ITEM_TOTAL_SET_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(M1.SHIPPING_TOTAL_AMOUNT) AS SHIPPING_TOTAL_AMOUNT, SUM(M1.ADD_PAYMENT_TOTAL_AMOUNT) AS ADD_PAYMENT_TOTAL_AMOUNT FROM ( SELECT M.SELLER_ID, M.OR_CNT, M.REMITTANCE_DATE, M.REMITTANCE_EXPECTED_DATE, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SUPPLY_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_POINT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SET_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS SHIPPING_TOTAL_AMOUNT, SUM(CASE WHEN M.PRODUCT_TYPE = 'ADD_PAYMENT' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ADD_PAYMENT_TOTAL_AMOUNT FROM (
