SELECT OS.SELLER_ID, COUNT(OS.SELLER_ID) as OR_CNT, 'SHIPPING' AS PRODUCT_TYPE, OS.REMITTANCE_DATE, OS.REMITTANCE_EXPECTED_DATE, SUM(CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT
