FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON OAP.SELLER_ID = S.SELLER_ID
