			AND OI.SELLER_ID != #{defaultOpmanagerSellerId}



			AND OI.SELLER_ID = #{sellerId}




		AND OI.REMITTANCE_EXPECTED_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
		AND OI.REMITTANCE_ID IS NULL
