/* saleson.shop.remittance.RemittanceMapper.insertRemittanceDetail */ INSERT INTO OP_REMITTANCE_DETAIL ( REMITTANCE_ID, ORDER_CODE, REMITTANCE_KEY, ITEM_TYPE, ITEM_USER_CODE, ITEM_NAME, OPTIONS, SALE_PRICE, SELLER_DISCOUNT_PRICE, SELLER_DISCOUNT_DETAIL, SELLER_POINT, SET_ITEM_FLAG, SET_DISCOUNT_PRICE, COMMISSION_BASE_PRICE, COMMISSION_RATE, COMMISSION_PRICE, COMMISSION_TYPE, SUPPLY_PRICE, REMITTANCE_PRICE, QUANTITY, CREATED_DATE ) SELECT #{remittanceId}, T.ORDER_CODE, T.REMITTANCE_KEY, T.PRODUCT_TYPE, T.ITEM_USER_CODE, T.ITEM_NAME, T.OPTIONS, T.SALE_PRICE, T.SELLER_DISCOUNT_PRICE, T.SELLER_DISCOUNT_DETAIL, T.SELLER_POINT, T.SET_ITEM_FLAG, T.SET_DISCOUNT_PRICE, T.COMMISSION_BASE_PRICE, T.COMMISSION_RATE, T.COMMISSION_PRICE, T.COMMISSION_TYPE, T.SUPPLY_PRICE, T.REMITTANCE_PRICE, T.QUANTITY,
FROM (
SELECT OI.ORDER_CODE, CONCAT('ITEM-', OI.ORDER_CODE, '-', OI.ORDER_SEQUENCE, '-', OI.ITEM_SEQUENCE) AS REMITTANCE_KEY, OI.ITEM_USER_CODE, OI.REMITTANCE_STATUS_CODE, 'ITEM' AS PRODUCT_TYPE, OI.REMITTANCE_DATE, OI.ITEM_NAME, OI.OPTIONS, OI.COMMISSION_BASE_PRICE, OI.COMMISSION_RATE, OI.COMMISSION_PRICE, OI.COMMISSION_TYPE, OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END) AS SELLER_DISCOUNT_PRICE, OI.SELLER_DISCOUNT_DETAIL, OI.SELLER_POINT, OI.SET_ITEM_FLAG, OI.SET_DISCOUNT_PRICE, OI.SALE_PRICE, (CASE WHEN OI.CANCEL_FLAG = 'Y' THEN -OI.SUPPLY_PRICE ELSE OI.SUPPLY_PRICE END) AS SUPPLY_PRICE, (CASE WHEN OI.CANCEL_FLAG = 'Y' THEN -OI.SUPPLY_PRICE + OI.SELLER_POINT + (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) + OI.SET_DISCOUNT_PRICE ELSE OI.SUPPLY_PRICE - OI.SELLER_POINT - (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) - OI.SET_DISCOUNT_PRICE END) AS REMITTANCE_PRICE, OI.QUANTITY FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OI.CANCEL_FLAG = 'Y'
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND OI.REMITTANCE_STATUS_CODE = '4'
AND OI.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OI.REMITTANCE_DATE = #{startDate}
AND OI.SUPPLY_PRICE > 0
UNION ALL
SELECT OS.ORDER_CODE, CONCAT('SHIPPING-', OS.ORDER_CODE, '-', OS.ORDER_SEQUENCE, '-', OS.SHIPPING_SEQUENCE) AS REMITTANCE_KEY, '' AS ITEM_USER_CODE, OS.REMITTANCE_STATUS_CODE, 'SHIPPING' AS PRODUCT_TYPE, OS.REMITTANCE_DATE, '배송비' AS ITEM_NAME, '' AS OPTIONS, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS COMMISSION_BASE_PRICE, 0 AS COMMISSION_RATE, 0 AS COMMISSION_PRICE, '0' AS COMMISSION_TYPE, 0 AS SELLER_DISCOUNT_PRICE, '' AS SELLER_DISCOUNT_DETAIL, 0 AS SELLER_POINT, '' AS SET_ITEM_FLAG, 0 AS SET_DISCOUNT_PRICE, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS SALE_PRICE, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS SUPPLY_PRICE, (CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS REMITTANCE_PRICE, 1 AS QUANTITY FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OS.SELLER_ID != #{defaultOpmanagerSellerId}
AND OS.SELLER_ID = #{sellerId}
AND REMITTANCE_STATUS_CODE = '4'
AND OS.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OS.REMITTANCE_DATE = #{startDate}
AND OS.REMITTANCE_AMOUNT > 0
UNION ALL
SELECT OAP.ORDER_CODE, CONCAT('ADD_PAYMENT-', OAP.ORDER_CODE, '-' , OAP.ADD_PAYMENT_ID) AS REMITTANCE_KEY, '' AS ITEM_USER_CODE, OAP.REMITTANCE_STATUS_CODE, 'ADD_PAYMENT' AS PRODUCT_TYPE, OAP.REMITTANCE_DATE, OAP.SUBJECT AS ITEM_NAME, '' AS OPTIONS, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS COMMISSION_BASE_PRICE, 0 AS COMMISSION_RATE, 0 AS COMMISSION_PRICE, '0' AS COMMISSION_TYPE, 0 AS SELLER_DISCOUNT_PRICE, '' AS SELLER_DISCOUNT_DETAIL, 0 AS SELLER_POINT, '' AS SET_ITEM_FLAG, 0 AS SET_DISCOUNT_PRICE, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS SALE_PRICE, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS SUPPLY_PRICE, (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS REMITTANCE_PRICE, 1 AS QUANTITY FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}
AND OAP.SELLER_ID = #{sellerId}
AND REMITTANCE_STATUS_CODE = '4'
AND OAP.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OAP.REMITTANCE_DATE = #{startDate}
AND OAP.REMITTANCE_AMOUNT > 0
) AS T

