	OP_ORDER_ADD_PAYMENT OAP
		INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
SET
	OAP.REMITTANCE_STATUS_CODE = '4'


