/* saleson.shop.remittance.RemittanceMapper.getRemittanceDateBySellerId */ SELECT IFNULL( DATE_FORMAT(
ADDDATE(CONCAT(DATE_FORMAT(NOW(), '%Y%m'), IF(LENGTH(S.REMITTANCE_DAY) = 1, CONCAT('0', S.REMITTANCE_DAY), S.REMITTANCE_DAY)), INTERVAL 1 MONTH)
, '%Y%m%d'), DATE_FORMAT(ADDDATE(NOW(), INTERVAL 1 DAY), '%Y%m%d') ) AS REMITTANCE_DATE FROM OP_SELLER S
S.SELLER_ID = #{value}

mapper.update:
/* saleson.shop.remittance.RemittanceMapper.updateResidualShippingRemittanceByRefundCode */ UPDATE OP_ORDER_SHIPPING OS INNER JOIN ( SELECT OI.ORDER_CODE, OI.ORDER_SEQUENCE, OI.SHIPPING_SEQUENCE, COUNT(*) AS ITEM_COUNT, SUM(CASE WHEN OI.CANCEL_FLAG = 'Y' THEN 1 ELSE 0 END) AS CANCEL_COUNT FROM OP_ORDER_ITEM OI INNER JOIN (
SELECT ORDER_CODE, ORDER_SEQUENCE, ITEM_SEQUENCE FROM OP_ORDER_CANCEL_APPLY WHERE REFUND_CODE = #{value}
UNION ALL
SELECT ORDER_CODE, ORDER_SEQUENCE, ITEM_SEQUENCE FROM OP_ORDER_RETURN_APPLY WHERE REFUND_CODE = #{value}
) T ON OI.ORDER_CODE = T.ORDER_CODE AND OI.ORDER_SEQUENCE = T.ORDER_SEQUENCE AND OI.ITEM_SEQUENCE = T.ITEM_SEQUENCE GROUP BY OI.ORDER_CODE, OI.ORDER_SEQUENCE, OI.SHIPPING_SEQUENCE ) T ON OS.ORDER_CODE = T.ORDER_CODE AND OS.ORDER_SEQUENCE = T.ORDER_SEQUENCE AND OS.SHIPPING_SEQUENCE = T.SHIPPING_SEQUENCE
SET OS.REMITTANCE_EXPECTED_DATE = ( SELECT IFNULL( DATE_FORMAT(
ADDDATE(CONCAT(DATE_FORMAT(NOW(), '%Y%m'), IF(LENGTH(S.REMITTANCE_DAY) = 1, CONCAT('0', S.REMITTANCE_DAY), S.REMITTANCE_DAY)), INTERVAL 1 MONTH)
, '%Y%m%d'), DATE_FORMAT(ADDDATE(NOW(), INTERVAL 1 DAY), '%Y%m%d') ) AS REMITTANCE_DATE FROM OP_SELLER S
S.SELLER_ID = OS.SELLER_ID
) WHERE OS.REMITTANCE_AMOUNT > 0 AND T.ITEM_COUNT = T.CANCEL_COUNT

/* saleson.shop.remittance.RemittanceMapper.updateItemRemittanceInfo */
UPDATE OP_ORDER_ITEM SET
	REMITTANCE_STATUS_CODE = '2',
	REMITTANCE_DATE = '',
	REMITTANCE_EXPECTED_DATE = #{remittanceExpectedDate},
	RETURN_POINT_FLAG = 'Y'
WHERE
	ORDER_CODE = #{orderCode}
	AND ORDER_SEQUENCE = #{orderSequence}
	AND ITEM_SEQUENCE = #{itemSequence}
	AND REMITTANCE_STATUS_CODE = '9'

/* saleson.shop.remittance.RemittanceMapper.updateAddPaymentRemittanceInfo */
UPDATE OP_ORDER_ADD_PAYMENT SET
	REMITTANCE_EXPECTED_DATE = #{remittanceExpectedDate}
WHERE
	ADD_PAYMENT_ID = #{addPaymentId}

