/* saleson.shop.remittance.RemittanceMapper.getRemittanceConfirmListByParamNew */
SELECT S.* , R.REMITTANCE_STATUS_CODE , R.CONFIRM_DATE , R.CONFIRM_DATE_SELLER , R.PAYMENT_DATE , R.FINISHING_DATE , R.FINISHING_AMOUNT , (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV L WHERE L.LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM , RD.* , (SELECT COUNT(1) FROM G_REMITTANCE_FILE RF WHERE RF.REMITTANCE_ID = R.REMITTANCE_ID ) AS FILE_CNT FROM ( SELECT COUNT(REMITTANCE_ID) AS REMI_DETAIL_CNT , REMITTANCE_ID , SUM(COMMISSION_BASE_PRICE * QUANTITY + ETC_AMT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT , SUM(COMMISSION_PRICE * QUANTITY + ETC_AMT) AS ITEM_TOTAL_COMMISSION_AMOUNT , SUM(SUPPLY_PRICE * QUANTITY + ETC_AMT) AS ITEM_TOTAL_SUPPLY_AMOUNT , SUM(SELLER_DISCOUNT_PRICE * QUANTITY) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT , SUM(SELLER_POINT * QUANTITY) AS ITEM_TOTAL_SELLER_POINT_AMOUNT , SUM(SET_DISCOUNT_PRICE * QUANTITY) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT FROM OP_REMITTANCE_DETAIL GROUP BY REMITTANCE_ID ) RD JOIN OP_REMITTANCE R ON R.REMITTANCE_ID = RD.REMITTANCE_ID JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID WHERE 1=1
AND R.SELLER_ID != #{defaultOpmanagerSellerId}
AND R.SELLER_ID = #{sellerId}
AND (R.REMITTANCE_STATUS_CODE = '3' OR R.REMITTANCE_STATUS_CODE = '4')
AND R.REMITTANCE_STATUS_CODE = '3'
AND R.REMITTANCE_STATUS_CODE = '4'
AND S.REPRESENTATIVE_NAME = #{query}
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
AND R.CONFIRM_DATE BETWEEN #{startDate} AND #{endDate}
AND R.CONFIRM_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND R.CONFIRM_DATE = #{startDate}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
ORDER BY R.REMITTANCE_ID DESC

