			AND R.REMITTANCE_STATUS_CODE = '3'


			AND R.REMITTANCE_STATUS_CODE = '4'






			AND R.CONFIRM_DATE BETWEEN #{startDate} AND #{endDate}



			AND R.CONFIRM_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')


			AND R.CONFIRM_DATE = #{startDate}




			AND S.REPRESENTATIVE_NAME = #{query}


			AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')




