				AND S.LOCGOV_CODE IN (
					SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr}
				)

/* saleson.shop.remittance.RemittanceMapper.getRemittanceConfirmDetailCountByParamNew */

SELECT
		COUNT(1)

			FROM OP_REMITTANCE_DETAIL RD
		JOIN OP_REMITTANCE R ON R.REMITTANCE_ID = RD.REMITTANCE_ID
		LEFT JOIN OP_ORDER_ITEM OI ON RD.ORDER_CODE = OI.ORDER_CODE AND RD.ITEM_SEQUENCE = OI.ITEM_SEQUENCE AND OI.ORDER_SEQUENCE = RD.ORDER_SEQUENCE AND RD.ITEM_TYPE = 'ITEM'
		LEFT JOIN OP_USER U ON OI.USER_ID = U.USER_ID
		WHERE 1 = 1



						AND RD.ORDER_CODE LIKE CONCAT('%', #{query} , '%')


						AND U.USER_NAME = #{query}


						AND RD.ITEM_USER_CODE LIKE CONCAT('%', #{query} , '%')


						AND RD.ITEM_NAME LIKE CONCAT('%', #{query} , '%')





				AND OI.SELLER_ID != #{defaultOpmanagerSellerId}



				AND OI.SELLER_ID = #{sellerId}

			AND (R.REMITTANCE_STATUS_CODE = '3' OR R.REMITTANCE_STATUS_CODE = '4')

			AND R.REMITTANCE_ID = #{remittanceId}

/* saleson.shop.remittance.RemittanceMapper.getRemittanceConfirmDetailListByParamNew */
SELECT T_A.* , T_A.BUYER_NAME_ENC AS BUYER_NAME FROM (
SELECT RD.ORDER_CODE , RD.ORDER_SEQUENCE , RD.ITEM_SEQUENCE , RD.REMITTANCE_DETAIL_ID
, RD.REMITTANCE_KEY , RD.ITEM_TYPE , RD.ITEM_USER_CODE , RD.ITEM_NAME , RD.OPTIONS , RD.SALE_PRICE , RD.COMMISSION_BASE_PRICE , RD.REMITTANCE_PRICE , RD.QUANTITY , RD.ETC_AMT
, R.REMITTANCE_STATUS_CODE , R.REMITTANCE_ID , R.CONFIRM_DATE AS REMITTANCE_DATE , OI.USER_ID , U.USER_NAME AS BUYER_NAME_ENC , OI.PAY_DATE , OI.CONFIRM_DATE , OI.SELLER_ID FROM OP_REMITTANCE_DETAIL RD JOIN OP_REMITTANCE R ON R.REMITTANCE_ID = RD.REMITTANCE_ID LEFT JOIN OP_ORDER_ITEM OI ON RD.ORDER_CODE = OI.ORDER_CODE AND RD.ITEM_SEQUENCE = OI.ITEM_SEQUENCE AND OI.ORDER_SEQUENCE = RD.ORDER_SEQUENCE AND RD.ITEM_TYPE = 'ITEM' LEFT JOIN OP_USER U ON OI.USER_ID = U.USER_ID WHERE 1 = 1
AND RD.ORDER_CODE LIKE CONCAT('%', #{query} , '%')
AND U.USER_NAME = #{query}
AND RD.ITEM_USER_CODE LIKE CONCAT('%', #{query} , '%')
AND RD.ITEM_NAME LIKE CONCAT('%', #{query} , '%')
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND R.REMITTANCE_ID = #{remittanceId} AND (R.REMITTANCE_STATUS_CODE = '3' OR R.REMITTANCE_STATUS_CODE = '4')
ORDER BY OI.CONFIRM_DATE DESC
) T_A

