/* saleson.shop.remittance.RemittanceMapper.getRemittanceFinishingListByParamNew */
SELECT S.*, (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV L WHERE L.LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM, R.REMITTANCE_ID, (SELECT COUNT(RD.REMITTANCE_ID) from OP_REMITTANCE_DETAIL RD WHERE RD.REMITTANCE_ID = R.REMITTANCE_ID) as OR_CNT, R.CONFIRM_DATE, R.FINISHING_DATE, R.FINISHING_AMOUNT, R.FINISHING_MANAGER_NAME, R.REMITTANCE_STATUS_CODE, R.CONFIRM_DATE_SELLER, R.PAYMENT_DATE, R.BANK_NAME AS REMITTANCE_BANK_NAME, R.BANK_IN_NAME AS REMITTANCE_BANK_IN_NAME, R.BANK_ACCOUNT_NUMBER AS REMITTANCE_BANK_ACCOUNT_NUMBER, R.CREATED_DATE AS REMITTANCE_CREATED_DATE, (SELECT REMITTANCE_STATUS_CODE FROM OP_ORDER_ITEM WHERE REMITTANCE_ID = R.REMITTANCE_ID LIMIT 1) AS REMITTANCE_STATUS_CODE, (SELECT SUM(T.TOTAL) AS TOTAL FROM ( SELECT (CASE WHEN OI.CANCEL_FLAG = 'Y' THEN -OI.SUPPLY_PRICE + OI.SELLER_POINT + (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) + OI.SET_DISCOUNT_PRICE ELSE OI.SUPPLY_PRICE - OI.SELLER_POINT - (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) - OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY AS TOTAL FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OI.REMITTANCE_ID = R.REMITTANCE_ID
UNION ALL
SELECT (CASE WHEN OS.RETURN_FLAG = 'Y' THEN -OS.REMITTANCE_AMOUNT ELSE OS.REMITTANCE_AMOUNT END) AS TOTAL FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OS.REMITTANCE_ID = R.REMITTANCE_ID
UNION ALL
SELECT (CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OAP.REMITTANCE_ID = R.REMITTANCE_ID ) T) AS SALES_AMOUNT FROM OP_REMITTANCE R INNER JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID
AND R.SELLER_ID = #{sellerId}
AND R.PAYMENT_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND R.PAYMENT_DATE BETWEEN #{startDate} AND #{endDate}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
AND S.REPRESENTATIVE_NAME = #{query}
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
AND R.REMITTANCE_STATUS_CODE = #{searchStatus}
AND (R.REMITTANCE_STATUS_CODE = '5' OR R.REMITTANCE_STATUS_CODE = '9')
ORDER BY R.REMITTANCE_ID DESC

