FROM
	OP_REMITTANCE_DETAIL RD

	RD.REMITTANCE_ID = #{remittanceId}

/* saleson.shop.remittance.RemittanceMapper.getRemittanceFinishingDetailListByParamNew */ SELECT * , ( SELECT USER_NAME FROM ( SELECT U.USER_NAME FROM OP_USER U WHERE U.USER_ID = ( SELECT USER_ID FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = DTL.ORDER_CODE LIMIT 1 ) ) ) AS BUYER_NAME FROM (
SELECT RD.* , ( SELECT PAY_DATE FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = RD.ORDER_CODE LIMIT 1 ) AS PAY_DATE , ( SELECT CONFIRM_DATE FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = RD.ORDER_CODE LIMIT 1 ) AS CONFIRM_DATE FROM OP_REMITTANCE_DETAIL RD
RD.REMITTANCE_ID = #{remittanceId}
ORDER BY CONFIRM_DATE DESC
) DTL

