INSERT INTO G_REMITTANCE_FILE(
	REMITTANCE_ID
	, FILE_SEQ
	, FILE_NAME
	, PATH_NAME
	, ORG_FILE_NAME
	, FRST_REGISTER_ID
	, FRST_REGIST_PNTTM
	, LAST_UPDUSR_ID
	, LAST_UPDT_PNTTM
) VALUES


(
	#{item.remittanceId}
	, #{item.fileSeq}
	, #{item.fileName}
	, #{item.pathName}
	, #{item.orgFileName}
	, #{item.frstRegisterId}
	, #{item.frstRegistPnttm}
	, #{item.frstRegisterId}
	, #{item.frstRegistPnttm}
)

