/* saleson.shop.remittance.RemittanceMapper.getRemittanceFileListForSeller */ SELECT R.REMITTANCE_ID , R.REMITTANCE_STATUS_CODE , FILE_SEQ , ORG_FILE_NAME , PATH_NAME , FILE_NAME , RF.LAST_UPDUSR_ID , RF.LAST_UPDT_PNTTM FROM OP_REMITTANCE R JOIN G_REMITTANCE_FILE RF ON RF.REMITTANCE_ID = R.REMITTANCE_ID JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID WHERE R.REMITTANCE_ID = #{remittanceId}
AND R.SELLER_ID = #{sellerId}
AND S.LOCGOV_CODE = #{locgovCode}
AND RF.FRST_REGIST_PNTTM BETWEEN CONCAT(#{uploadDate}, '000000') AND CONCAT(#{uploadDate}, '235959')
ORDER BY LAST_UPDT_PNTTM DESC

/* saleson.shop.remittance.RemittanceMapper.getRemittanceFileMaxSequence */
SELECT
	R.REMITTANCE_ID
	, R.REMITTANCE_STATUS_CODE
	, IFNULL(MAX(RF.FILE_SEQ), 0) AS FILE_SEQ
	FROM OP_REMITTANCE R
		LEFT JOIN G_REMITTANCE_FILE RF ON RF.REMITTANCE_ID = R.REMITTANCE_ID
		LEFT JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID
	WHERE R.REMITTANCE_ID = #{remittanceId}

			AND R.SELLER_ID = #{sellerId}


			AND S.LOCGOV_CODE = #{locgovCode}

	GROUP BY R.REMITTANCE_ID

/* saleson.shop.remittance.RemittanceMapper.getRemittanceFile */
SELECT
	R.REMITTANCE_ID
	, R.REMITTANCE_STATUS_CODE
	, RF.FILE_NAME
	, RF.ORG_FILE_NAME
	, RF.PATH_NAME
	FROM OP_REMITTANCE R
		LEFT JOIN G_REMITTANCE_FILE RF ON RF.REMITTANCE_ID = R.REMITTANCE_ID
		LEFT JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID
	WHERE R.REMITTANCE_ID = #{remittanceId}
		AND RF.FILE_SEQ = #{fileSeq}

			AND R.SELLER_ID = #{sellerId}


			AND S.LOCGOV_CODE = #{locgovCode}

